// Data atual de São Paulo e Dia do Ano
function getDayOfYearSP() {
  const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = now - start + ((start.getTimezoneOffset() - now.getTimezoneOffset()) * 60 * 1000);
  const oneDay = 1000 * 60 * 60 * 24;
  return {
    doy: Math.min(365, Math.max(1, Math.floor(diff / oneDay))),
    iso: now.toISOString().slice(0, 10),
    year: now.getFullYear()
  };
}
const todayInfo = getDayOfYearSP();

// HTTP helper para Conecta King API
async function ck(method, path, body) {
  const opts = {
    method,
    url: base + path,
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json',
      ...(token ? { 'Authorization': 'Bearer ' + token } : {})
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

// HTTP helper para OpenAI API
async function openaiCall(payload) {
  return this.helpers.httpRequest.call(this, {
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + openaiKey,
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    },
    body: payload,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
}

