let outMessage = '';

try {
  if (!openaiKey) {
    const r = await ck.call(this, 'GET', '/api/bible/verse-of-day');
    const v = (r.body && r.body.data) || {};
    outMessage = `🕊️ *A paz do Senhor, ${firstName}!*\n\n📖 *Versículo do Dia:*\n_\"${v.texto || 'O Senhor é o meu pastor; de nada terei falta.'}\"_\n— *${v.ref || 'Salmos 23:1'}*\n\n✨ _${v.reflexao || 'Confie no cuidado e na provisão divina para o seu dia.'}_\n\nComo posso orar ou estudar a Palavra com você hoje?`;
  } else {
    const inputForAi = (hadVoice ? '[áudio transcrito] ' : '') + (text || 'A paz do Senhor!');
    const messages = [
      { role: 'system', content: SYSTEM_PROMPT },
      ...session.history.slice(-6),
      { role: 'user', content: inputForAi }
    ];

    const completionRes = await openaiCall.call(this, {
      model,
      temperature: 0.2,
      messages,
      tools: TOOLS,
      tool_choice: 'auto'
    });

    const choice = completionRes.body?.choices?.[0]?.message;

    if (choice?.tool_calls && choice.tool_calls.length > 0) {
      const toolCall = choice.tool_calls[0];
      const fnName = toolCall.function.name;
      let args = {};
      try { args = JSON.parse(toolCall.function.arguments || '{}'); } catch (_) {}

      // 1. TEMAS MENSAIS DOS DEVOCIONAIS (ADMIN)
      if (fnName === 'admin_set_month_themes') {
        const year = Number(args.year || todayInfo.year);
        if (args.action === 'set' && args.themes) {
          const currentRes = await ck.call(this, 'GET', `/api/admin/bible/devotionals-365/month-themes/${year}`);
          const currentThemes = (currentRes.body && (currentRes.body.data?.themes || currentRes.body.themes)) || {};
          const mergedThemes = { ...currentThemes, ...args.themes };

          const r = await ck.call(this, 'PUT', `/api/admin/bible/devotionals-365/month-themes/${year}`, mergedThemes);
          if (r.statusCode >= 200 && r.statusCode < 300) {
            const monthsNames = ['', 'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
            const lines = [`🗓️ *Temas Mensais de Devocionais Gravados (${year})!*\n`];
            for (const [m, t] of Object.entries(args.themes)) {
              const mNum = Number(m);
              const mName = monthsNames[mNum] || `Mês ${mNum}`;
              lines.push(`• *${mName} (Mês ${mNum}):* ${t}`);
            }
            lines.push(`\n✅ _Salvo com sucesso na base do servidor! Já orientará as próximas gerações de devocionais._`);
            outMessage = lines.join('\n');
          } else {
            outMessage = `⚠️ Erro ao salvar temas: ${r.body?.message || JSON.stringify(r.body)}`;
          }
        } else if (args.action === 'generate_all_ai') {
          const r = await ck.call(this, 'POST', `/api/admin/bible/devotionals-365/month-themes/${year}/generate-all`, { delayMs: 300 });
          if (r.statusCode >= 200 && r.statusCode < 300) {
            outMessage = `⚡ *Linha Editorial Completa para ${year} Gerada com IA!*\n\nTodos os 12 meses receberam temas teológicos profundos e inspiradores na plataforma.`;
          } else {
            outMessage = `⚠️ Erro ao gerar temas: ${r.body?.message}`;
          }
        } else {
          const r = await ck.call(this, 'GET', `/api/admin/bible/devotionals-365/month-themes/${year}`);
          const th = (r.body && (r.body.data?.themes || r.body.themes)) || {};
          const monthsNames = ['', 'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
          const lines = [`🗓️ *Temas dos Meses (${year}):*\n`];
          for (let i = 1; i <= 12; i++) {
            lines.push(`• *${monthsNames[i]}:* ${th[i] || '—'}`);
          }
          outMessage = lines.join('\n');
        }

      // 2. EDITAR VERSÍCULO DO DIA (ADMIN)
      } else if (fnName === 'admin_edit_verse_of_day') {
        const targetDate = args.date || todayInfo.iso;
        const payload = {
          date: targetDate,
          ref: args.ref,
          texto: args.texto,
          reflexao: args.reflexao || ''
        };
        const r = await ck.call(this, 'PUT', '/api/admin/bible/verse-of-day', payload);
