          if (r.statusCode >= 200 && r.statusCode < 300) {
            outMessage = `✨ *Devocional #${targetDay} Gravado no Servidor!*\n\n📖 *Título:* ${payload.titulo}\n📍 *Passagem:* ${payload.versiculo_ref}\n${payload.versiculo_texto ? '📜 *Versículo:* _"' + payload.versiculo_texto + '"_\n\n' : ''}📝 *Reflexão:*\n${payload.reflexao}\n\n${payload.aplicacao ? '🎯 *Aplicação Prática & Reprogramação:*\n' + payload.aplicacao + '\n\n' : ''}🙏 *Oração Pastoral:*\n_${payload.oracao}_\n\n✅ _Salvo com sucesso na base oficial dos 365 dias!_`;
