            const vText = d.versiculo_texto ? '📜 *Versículo:* _"' + d.versiculo_texto + '"_\n\n' : '';
            const refl = d.reflexao || d.texto || '';
            const pray = d.oracao || '';
            const apl = d.aplicacao || '';

            outMessage = `⚡ *Devocional #${targetDay} Gerado com IA & Gravado!*\n\n📖 *Título:* ${d.titulo || 'Novo Devocional'}\n📍 *Passagem:* ${refTitle}\n\n${vText}📝 *Reflexão (Teologia, Neurociência & Desbloqueio):*\n${refl}\n\n${apl ? '🎯 *Neuro-Ação & Reprogramação Prática:*\n' + apl + '\n\n' : ''}🙏 *Oração Pastoral:*\n_${pray || 'Amém.'}_\n\n✅ _Publicado e ativo no Conecta King!_`;
          } else {
            outMessage = `⚠️ Erro ao gerar com IA: ${r.body?.message || JSON.stringify(r.body)}`;
          }
        } else if (args.action === 'delete') {
          const r = await ck.call(this, 'DELETE', `/api/admin/bible/devotionals-365/${targetDay}`);
          outMessage = r.statusCode < 300 ? `🗑️ *Devocional #${targetDay} Removido com Sucesso!* Dia liberado para nova redação.` : `⚠️ Erro ao remover: ${r.body?.message}`;
        } else {
          const r = await ck.call(this, 'GET', `/api/admin/bible/devotionals-365/day/${targetDay}`);
