            outMessage = `🌙 *Ativação de Prosperidade #${n} Salva!*\n\n💎 *Título:* ${payload.titulo}\n📖 *Palavra Base:* ${payload.proverbs_ref}\n🕊️ *Fundamento:* ${payload.fundamento_sagrado}\n\n🗣️ *Decreto para Antes de Dormir:*\n_\"${payload.decreto_entrada}\"_\n\n💡 *Nova Mentalidade:* ${payload.nova_mentalidade}\n\n📢 *Status:* ${payload.published ? '✅ Publicada na plataforma' : '🟡 Rascunho'}`;
          } else {
            outMessage = `⚠️ Erro ao salvar ativação: ${r.body?.message || JSON.stringify(r.body)}`;
          }
        } else if (args.action === 'publish') {
          const pub = args.published !== false;
          const r = await ck.call(this, 'PATCH', `/api/admin/bible/prosperidade/${n}/publish`, { published: pub });
          outMessage = r.statusCode < 300 ? `📢 *Ativação #${n} ${pub ? 'Publicada com Sucesso! Já visível para todos.' : 'Despublicada (Rascunho)'}*` : `⚠️ Erro ao alterar status: ${r.body?.message}`;
        } else if (args.action === 'generate_ai') {
