        const vTexto = d.versiculo_texto ? `"${d.versiculo_texto}"\n\n` : '';
        const texto = d.reflexao || d.texto || d.content || d.meditacao || '';
        const oracao = d.oracao || d.prayer || '';
        const aplicacao = d.aplicacao || d.application || '';
        outMessage = `🌅 *Devocional do Dia:* ${titulo}\n\n📖 *Texto Base:* ${passagem}\n\n${vTexto}${texto}\n\n${aplicacao ? '🎯 *Aplicação Prática:*\n' + aplicacao + '\n\n' : ''}${oracao ? '🙏 *Oração:*\n_' + oracao + '_\n\n' : ''}Amém! Que Deus abençoe sua jornada. 🙌`;
      } else if (fnName === 'get_salmo_do_dia') {
        const r = await ck.call(this, 'GET', '/api/bible/salmo-do-dia');
        const s = (r.body && r.body.data) || {};
        const ref = s.ref || 'Salmos';
        const texto = s.texto || '';
        const reflexao = s.reflexao || '';
        outMessage = `🛡️ *Salmo do Dia:* ${ref}\n\n"${texto}"\n\n${reflexao ? '🕊️ *Meditação:*\n' + reflexao + '\n\n' : ''}Que o Senhor seja o seu refúgio e fortaleza hoje! 🙌`;
      } else if (fnName === 'get_prosperidade_hoje') {
        const path = args.day ? '/api/bible/prosperidade/ativacao/' + args.day : '/api/bible/prosperidade/hoje';
        const r = await ck.call(this, 'GET', path);
        const p = (r.body && r.body.data) || {};
        const num = p.numero || p.day || p.dia || '365';
        const titulo = p.titulo || p.title || 'Ativação Bíblica de Prosperidade';
        const versiculo = p.versiculo || p.verse || '';
        const declaracao = p.declaracao || p.affirmation || '';
        const chave = p.chave || p.chave_prosperidade || p.principio || '';
        const acao = p.acao_pratica || p.action || '';
        outMessage = `🌙 *Ativação Noturna de Prosperidade #${num}*\n\n💎 *${titulo}*\n\n📖 *Princípio Bíblico:*\n"${versiculo}"\n\n${chave ? '🔑 *Chave de Sabedoria:* ' + chave + '\n\n' : ''}${declaracao ? '🗣️ *Declaração de Fé:*\n_"' + declaracao + '"_\n\n' : ''}${acao ? '🎯 *Passo Prático:*\n' + acao + '\n\n' : ''}Deus tem prazer na prosperidade integral da sua vida!`;
      } else if (fnName === 'get_bible_text') {
        const bookId = String(args.book_id || 'salmos').toLowerCase();
        const cap = Number(args.chapter || 1);
        const r = await ck.call(this, 'GET', `/api/bible/book/${bookId}/${cap}`);
        const data = (r.body && r.body.data) || {};
        const bookName = data.book?.name || bookId.toUpperCase();
        const verses = data.verses || data.versiculos || [];
        if (Array.isArray(verses) && verses.length > 0) {
          const sample = verses.slice(0, 10).map(v => `*${v.number || v.verse}* ${v.text}`).join('\n\n');
          outMessage = `📖 *${bookName} ${cap}*\n\n${sample}${verses.length > 10 ? '\n\n_(Exibindo os primeiros 10 versículos de ' + verses.length + ' motivado por espaço no Telegram)_' : ''}`;
        } else {
          outMessage = `📖 *Leitura de ${bookName} ${cap}* consultada na plataforma.`;
        }
      } else if (fnName === 'generate_sermon_outline') {
        const theme = args.theme;
        const pass = args.passage || 'Escrituras';
        const aud = args.audience ? ` (Público: ${args.audience})` : '';
        const sermonRes = await openaiCall.call(this, {
          model,
          temperature: 0.4,
          messages: [
            { role: 'system', content: 'Você é um pregador e mestre bíblico expositivo de alto nível. Crie um esboço exegético e claro de sermão contendo: 1. Título impactante e memorável; 2. Texto Base com contexto histórico-cultural e etimológico; 3. Introdução cativante que conecte com a realidade humana; 4. Três pontos principais expositivos profundamente alicerçados nas escrituras e na neurociência da transformação pessoal; 5. Aplicação prática para o cotidiano; 6. Conclusão profética e apelo/oração pastoral.' },
            { role: 'user', content: `Elabore um esboço de pregação sobre o tema: \"${theme}\", baseado em \"${pass}\"${aud}.` }
          ]
        });
        outMessage = sermonRes.body?.choices?.[0]?.message?.content || `📋 *Esboço de Pregação: ${theme}*\n\n📖 Base: ${pass}`;
      } else if (fnName === 'pastoral_prayer_counsel') {
        const prayerRes = await openaiCall.call(this, {
          model,
          temperature: 0.4,
          messages: [
            { role: 'system', content: 'Você é um pastor amoroso, sábio e com profunda unção espiritual e psicológica. Escreva uma oração pastoral profunda, bíblica e restauradora, trazendo paz ao sistema límbico/nervoso da pessoa, destruindo sentimentos de medo, abandono e culpa, e liberando bênçãos e decretos de vida e vitória.' },
            { role: 'user', content: `Faça uma oração pastoral para ${args.name || firstName}, que necessita de intercessão e direção sobre: ${args.need}.` }
          ]
        });
        outMessage = prayerRes.body?.choices?.[0]?.message?.content || `🙏 Que a paz que excede todo entendimento guarde o seu coração e a sua mente em Cristo Jesus.`;
      }
    } else {
      outMessage = choice?.content || `A paz do Senhor, ${firstName}! Estou aqui como Conselheiro Bíblico da Conecta King. O que você gostaria de criar, editar ou estudar na Palavra hoje?`;
    }

    // Diagnóstico removido

    session.history.push({ role: 'user', content: inputForAi });
    session.history.push({ role: 'assistant', content: outMessage });
    if (session.history.length > 12) session.history.splice(0, 2);
  }
} catch (e) {
  outMessage = '���️ Graça e Paz! Ocorreu uma oscilação momentânea: ' + String(e.message || e).slice(0, 200) + '\n\nComo posso abençoar seus estudos na Palavra hoje?';
}

return [{ json: { ...prev, outMessage } }];
